def gaps(results):
    return sorted(r.get('scope') for r in results
                  if r.get('status') != 'ok' or not isinstance(r.get('findings'), list))

def orchestrate(results, budget):
    tokens = sum(r['tokens'] for r in results)
    values = {}
    for r in results:
        if r['status'] == 'ok':
            for item, v in r['claims'].items():
                values.setdefault(item, set()).add(v)
    conflicts = sorted(i for i, vs in values.items() if len(vs) > 1)
    if tokens > budget:
        verdict = 'over_budget'
    elif any(r['status'] != 'ok' for r in results):
        verdict = 'blocked'
    elif conflicts:
        verdict = 'review'
    else:
        verdict = 'ready'
    return {'tokens': tokens, 'conflicts': conflicts, 'verdict': verdict}
